python3 &lt;span class="nt"&gt;-m&lt;/span&gt; peakweek &lt;span class="nt"&gt;--fixture&lt;/span&gt; examples/forecast_burlington.json      &lt;span class="c"&gt;# the same card, in the terminal&lt;/span&gt;
